        'data_availability_policy'=>['title'=>'Disponibilité des données et reproductibilité','body'=>'Les recherches indiquent où consulter données, code et matériel, ou justifient les restrictions éthiques, juridiques, commerciales ou de sécurité. Les méthodes doivent permettre l’évaluation scientifique.'],
        'misconduct_policy'=>['title'=>'Inconduite scientifique','body'=>'Les allégations de fabrication, falsification, plagiat, conflit caché ou manipulation de l’évaluation sont examinées confidentiellement, preuves et droit de réponse à l’appui, avec correction, rejet ou rétractation proportionnée. Aucune adhésion externe n’est sous-entendue.'],
        'appeals_policy'=>['title'=>'Plaintes et recours','body'=>'Auteur ou lecteur peut adresser au courriel officiel une plainte ou un recours précis et étayé. Si possible, une personne étrangère à la décision contestée le réexamine; le simple désaccord ne renverse pas un jugement scientifique.'],
        'privacy_policy'=>['title'=>'Protection des données et confidentialité','body'=>'Seules les métadonnées utiles sont publiques. Coordonnées, manuscrits, identité des évaluateurs et commentaires confidentiels restent chiffrés ou soumis à contrôle d’accès et servent uniquement aux opérations éditoriales légitimes.'],
        'preservation_policy'=>['title'=>'Préservation numérique','body'=>'Les versions publiées conservent empreinte cryptographique et historique immuable. Le lancement exige aussi des sauvegardes protégées et actuelles; aucune participation à un réseau d’archivage externe n’est affirmée sans activation vérifiée.'],
        'licensing_policy'=>['title'=>'Droits et licences','body'=>'Chaque dossier affiche sa licence effective. Aucune licence ouverte n’est présumée sans sélection et autorisation explicites.'],
        'fees_policy'=>['title'=>'Frais et coûts de traitement','body'=>'La position actuelle sur frais et exonérations figure dans les informations ci-dessous. Aucun paiement non déclaré ne garantit évaluation, acceptation ou publication; l’adhésion professionnelle ne modifie pas les critères.'],
        'doi_policy'=>['title'=>'DOI et indexation','body'=>'DOI, ISSN, indexation et indicateurs n’apparaissent qu’après attribution ou vérification officielle. Aucun identifiant provisoire n’est présenté comme enregistrement externe.'],
    ],
]);
